import React, { useState } from 'react';
import { 
    Box, 
    TextField, 
    Button, 
    Typography, 
    IconButton, 
    Stack, 
    alpha,
    CircularProgress,
    MenuItem
} from '@mui/material';
import { 
    Add as AddIcon, 
    Delete as DeleteIcon, 
    FormatQuote as QuoteIcon,
    Person as AuthorIcon,
    AccessTime as TimeIcon,
    Today as DateIcon
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import { useSelector } from 'react-redux';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs from 'dayjs';

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const FREQUENCY_OPTIONS = [
    { label: 'Daily', value: 'daily' },
    { label: 'Weekly', value: 'weekly' },
    { label: 'One-off', value: 'one-off' },
];

const DAYS_OF_WEEK = [
    { label: 'Monday', value: 1 },
    { label: 'Tuesday', value: 2 },
    { label: 'Wednesday', value: 3 },
    { label: 'Thursday', value: 4 },
    { label: 'Friday', value: 5 },
    { label: 'Saturday', value: 6 },
    { label: 'Sunday', value: 7 },
];

const INITIAL_QUOTE_STATE = {
    text: '',
    author: '',
    frequency: 'daily',
    day_of_week: 1,
    scheduled_at: null
};

const FIELD_STYLE = {
    '& .MuiOutlinedInput-root': {
        backgroundColor: '#111111',
        borderRadius: '10px',
        height: '48px',
        '& fieldset': { 
            borderColor: 'rgba(255, 255, 255, 0.12)',
            transition: 'border-color 0.2s ease',
        },
        '&:hover fieldset': { 
            borderColor: 'rgba(255, 255, 255, 0.25)',
        },
        '&.Mui-focused fieldset': { 
            borderColor: '#4CC66E',
            borderWidth: '1.5px',
        },
        '& .MuiInputAdornment-root .MuiSvgIcon-root': {
            color: '#4CC66E',
            fontSize: '1.25rem'
        },
        '& .MuiSelect-icon': {
            color: '#4CC66E',
        }
    },
    '& .MuiInputBase-input': {
        color: '#FFFFFF',
        fontSize: '0.875rem',
        padding: '0 14px !important',
        height: '100%',
        '&::placeholder': {
            color: 'rgba(255, 255, 255, 0.35)',
            opacity: 1,
        }
    }
};

const AddQuotes = () => {
    const navigate = useNavigate();
    const token = useSelector((state) => state.auth.token);
    const [quotes, setQuotes] = useState([INITIAL_QUOTE_STATE]);
    const [isSaving, setIsSaving] = useState(false);
    const [openPickerIndex, setOpenPickerIndex] = useState(null);
    const [anchorEl, setAnchorEl] = useState(null);

    const handleQuoteChange = (index, field, value) => {
        setQuotes(prev => {
            const newQuotes = [...prev];
            newQuotes[index] = { ...newQuotes[index], [field]: value };
            return newQuotes;
        });
    };

    const addQuoteField = () => {
        setQuotes(prev => [...prev, { ...INITIAL_QUOTE_STATE }]);
        toast.success('New quote slot added!');
    };

    const removeQuoteField = (index) => {
        if (quotes.length > 1) {
            setQuotes(prev => prev.filter((_, i) => i !== index));
        }
    };

    const getPayload = (quote) => {
        const payload = {
            ...quote,
            scheduled_at: quote.frequency === 'one-off' && quote.scheduled_at 
                ? dayjs(quote.scheduled_at).format('YYYY-MM-DD')
                : null,
            day_of_week: quote.frequency === 'weekly' ? quote.day_of_week : null
        };
        // Remove frequency specific fields if not selected to keep payload clean
        if (quote.frequency !== 'weekly') delete payload.day_of_week;
        if (quote.frequency !== 'one-off') delete payload.scheduled_at;
        return payload;
    };

    const handleSaveAll = async () => {
        if (!token) return;
        
        // Validation
        const invalidQuotes = quotes.filter(q => 
            !q.text || 
            !q.author || 
            (q.frequency === 'one-off' && !q.scheduled_at)
        );
        
        if (invalidQuotes.length > 0) {
            toast.error('Please fill in all required fields for each quote');
            return;
        }

        setIsSaving(true);
        const toastId = toast.loading(`Saving ${quotes.length} quotes...`);

        try {
            const savePromises = quotes.map(quote => 
                fetch(`${BASE_URL}/motivational-quotes`, {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(getPayload(quote))
                }).then(res => res.json())
            );

            const results = await Promise.all(savePromises);
            
            const failures = results.filter(r => r.error);
            if (failures.length === 0) {
                toast.success('All quotes added successfully!', { id: toastId });
                navigate('/quotes');
            } else {
                toast.error(`${failures.length} quotes failed to save.`, { id: toastId });
            }
        } catch (error) {
            console.error('Save error:', error);
            toast.error('Something went wrong during bulk save', { id: toastId });
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <LocalizationProvider dateAdapter={AdapterDayjs}>
            <Box sx={{ 
                minHeight: '100vh', 
                m:2
            }}>
                
                {/* Header */}
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4, px: 2 }}>
                    <Typography variant="h5" sx={{ fontWeight: 900, fontSize: {xs: '1.5rem', md: '1.75rem'} }}>
                        Bulk Add Quotes
                    </Typography>
                    <Stack direction="row" spacing={2}>
                        <Button
                            variant="contained"
                            startIcon={<AddIcon />}
                            onClick={addQuoteField}
                            sx={{ 
                                borderRadius: '12px', 
                                textTransform: 'none', 
                                fontWeight: 700,
                                bgcolor: '#9F6EDA',
                                '&:hover': { bgcolor: alpha('#9F6EDA', 0.8) }
                            }}
                        >
                            Add
                        </Button>
                        
                    </Stack>
                </Box>

                {/* Content Area */}
                <Box sx={{ 
                    bgcolor: '#001e08', 
                    borderRadius: '24px', 
                    p: { xs: 2, md: 5 },
                    border: '1px solid rgba(255,255,255,0.05)',
                }}>
                    <Stack spacing={4}>
                        {quotes.map((quote, index) => (
                            <Box 
                                key={index} 
                                sx={{ 
                                    p: 3, 
                                    borderRadius: '20px', 
                                    bgcolor: alpha('#000', 0.2),
                                    border: '1px solid rgba(255,255,255,0.03)',
                                    position: 'relative'
                                }}
                            >
                                {quotes.length > 1 && (
                                    <IconButton 
                                        onClick={() => removeQuoteField(index)}
                                        sx={{ 
                                            position: 'absolute', 
                                            top: 12, 
                                            right: 12, 
                                            color: '#FF5050',
                                            bgcolor: alpha('#FF5050', 0.1),
                                            '&:hover': { bgcolor: alpha('#FF5050', 0.2) }
                                        }}
                                        size="small"
                                    >
                                        <DeleteIcon fontSize="small" />
                                    </IconButton>
                                )}

                                <Typography variant="subtitle2" sx={{ color: '#4CC66E', fontWeight: 800, mb: 3, display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Box sx={{ width: 24, height: 24, borderRadius: '6px', bgcolor: alpha('#4CC66E', 0.1), display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px' }}>
                                        {index + 1}
                                    </Box>
                                    QUOTE DETAILS
                                </Typography>

                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                                    <Box>
                                        <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 700, mb: 1, display: 'flex', alignItems: 'center', gap: 1, textTransform: 'uppercase' }}>
                                            <QuoteIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                                            Quote Content
                                        </Typography>
                                        <TextField
                                            fullWidth
                                            multiline
                                            rows={3}
                                            placeholder="Type your motivational quote here..."
                                            value={quote.text}
                                            onChange={(e) => handleQuoteChange(index, 'text', e.target.value)}
                                            required
                                            sx={{
                                                ...FIELD_STYLE,
                                                '& .MuiOutlinedInput-root': {
                                                    ...FIELD_STYLE['& .MuiOutlinedInput-root'],
                                                    height: 'auto',
                                                },
                                                '& .MuiInputBase-input': {
                                                    ...FIELD_STYLE['& .MuiInputBase-input'],
                                                    padding: '12px 14px !important',
                                                    height: 'auto'
                                                }
                                            }}
                                        />
                                    </Box>

                                    <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, gap: 3 }}>
                                        <Box sx={{ flex: 1 }}>
                                            <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 700, mb: 1, display: 'flex', alignItems: 'center', gap: 1, textTransform: 'uppercase' }}>
                                                <AuthorIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                                                Author
                                            </Typography>
                                            <TextField
                                                fullWidth
                                                placeholder="e.g. Arnold Schwarzenegger"
                                                value={quote.author}
                                                onChange={(e) => handleQuoteChange(index, 'author', e.target.value)}
                                                required
                                                sx={FIELD_STYLE}
                                            />
                                        </Box>

                                        <Box sx={{ flex: 1 }}>
                                            <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 700, mb: 1, display: 'flex', alignItems: 'center', gap: 1, textTransform: 'uppercase' }}>
                                                <TimeIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                                                Frequency
                                            </Typography>
                                            <TextField
                                                fullWidth
                                                select
                                                value={quote.frequency}
                                                onChange={(e) => handleQuoteChange(index, 'frequency', e.target.value)}
                                                required
                                                sx={FIELD_STYLE}
                                            >
                                                {FREQUENCY_OPTIONS.map(option => (
                                                    <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                                                ))}
                                            </TextField>
                                        </Box>

                                        {quote.frequency === 'weekly' && (
                                            <Box sx={{ flex: 1 }}>
                                                <Typography variant="caption" sx={{ color: '#8B8D97', fontWeight: 700, mb: 1, display: 'flex', alignItems: 'center', gap: 1, textTransform: 'uppercase' }}>
                                                    <DateIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                                                    Day of Week
                                                </Typography>
                                                <TextField
                                                    fullWidth
                                                    select
                                                    value={quote.day_of_week}
                                                    onChange={(e) => handleQuoteChange(index, 'day_of_week', e.target.value)}
                                                    required
                                                    sx={FIELD_STYLE}
                                                >
                                                    {DAYS_OF_WEEK.map(option => (
                                                        <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                                                    ))}
                                                </TextField>
                                            </Box>
                                        )}

                                        {quote.frequency === 'one-off' && (
                                          <Box sx={{ flex: 1 }}>
  <Typography
    variant="caption"
    sx={{
      color: '#8B8D97',
      fontWeight: 700,
      mb: 1,
      display: 'flex',
      alignItems: 'center',
      gap: 1,
      textTransform: 'uppercase'
    }}
  >
    <TimeIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
    Scheduled At
  </Typography>

  <TextField
    fullWidth
    placeholder="YYYY-MM-DD"
    value={quote.scheduled_at ? dayjs(quote.scheduled_at).format('YYYY-MM-DD') : ''}
    onClick={(e) => {
        setAnchorEl(e.currentTarget);
        setOpenPickerIndex(index);
    }}
    required
    sx={FIELD_STYLE}
    inputProps={{ readOnly: true }}
  />
  <DatePicker
    open={openPickerIndex === index}
    onClose={() => {
        setOpenPickerIndex(null);
        setAnchorEl(null);
    }}
    value={quote.scheduled_at ? dayjs(quote.scheduled_at) : null}
    onChange={(val) => {
        handleQuoteChange(index, 'scheduled_at', val);
        setOpenPickerIndex(null);
        setAnchorEl(null);
    }}
    slots={{
        field: () => null
    }}
    slotProps={{
        popper: {
            anchorEl: anchorEl,
            placement: 'bottom-start',
            sx: {
                '& .MuiPaper-root': {
                    bgcolor: '#111111',
                    color: '#FFF',
                    border: '1px solid rgba(255,255,255,0.1)',
                }
            }
        }
    }}
  />
</Box>
                                        )}
                                    </Box>
                                </Box>
                            </Box>
                        ))}
                    </Stack>

                    {/* Bottom Actions */}
                    <Box sx={{ 
                        display: 'flex', 
                        justifyContent: 'flex-end',
                        mt: 6, 
                        pt: 4, 
                        borderTop: '1px solid rgba(255,255,255,0.08)'
                    }}>
                        <Button 
                            variant="contained" 
                            color="secondary"
                            onClick={handleSaveAll}
                            disabled={isSaving}
                            sx={{ 
                                height: 52, 
                                minWidth: 200,
                                borderRadius: '14px',
                                textTransform: 'none',
                                fontWeight: 700,
                                fontSize: '1rem',
                                bgcolor: '#9F6EDA',
                                '&:hover': { bgcolor: alpha('#9F6EDA', 0.9) }
                            }}
                        >
                            {isSaving ? <CircularProgress size={24} sx={{ color: '#FFF' }} /> : `Save ${quotes.length} Quotes`}
                        </Button>
                    </Box>
                </Box>
            </Box>
        </LocalizationProvider>
    );
};

export default AddQuotes;


